import { FunctionComponent } from 'preact';
import { useState, useEffect, useRef, useId } from 'preact/hooks';
import { InputHTMLAttributes } from 'preact/compat';
import { classes, debounce } from '@adobe-commerce/elsie/lib';
import { Add, Minus } from '@adobe-commerce/elsie/icons';
import { Icon } from '@adobe-commerce/elsie/components/Icon';
import { Localizer, Text } from '@adobe-commerce/elsie/i18n';
import '@adobe-commerce/elsie/components/Incrementer/Incrementer.css';

export interface IncrementerProps extends Omit<
  InputHTMLAttributes<HTMLInputElement>,
  'size'
> {
  name?: string;
  label?: string;
  size?: 'medium' | 'large';
  onValue?: (value: any) => void;
  onUpdateError?: (error: Error) => void;
  error?: boolean;
  success?: boolean;
  min?: number;
  max?: number;
  disabled?: boolean;
  maxLength?: number;
  showButtons?: boolean;
}

export const Incrementer: FunctionComponent<IncrementerProps> = ({
  name,
  label,
  value = '1',
  className,
  disabled,
  error,
  success,
  min,
  max,
  onValue,
  onUpdateError,
  size = 'medium',
  showButtons = true,
  ...props
}) => {
  const [currentValue, setCurrentValue] = useState<number>(Number(value));
  const [isEmpty, setIsEmpty] = useState<boolean>(false);
  const isFocusedRef = useRef<boolean>(false);
  const inputId = useId();
  const minValue = Number(min);
  const maxValue = Number(max);
  const isInvalid =
    error || isEmpty || currentValue < minValue || currentValue > maxValue;

  const errorMessage = isEmpty
    ? 'Dropin.Incrementer.requiredMessage'
    : currentValue < minValue
      ? 'Dropin.Incrementer.minQuantityMessage'
      : currentValue > maxValue
        ? 'Dropin.Incrementer.maxQuantityMessage'
        : 'Dropin.Incrementer.errorMessage';

  // Keep callback refs current so debounced handlers never capture stale closures
  const onValueRef = useRef(onValue);
  useEffect(() => {
    onValueRef.current = onValue;
  }, [onValue]);

  const onUpdateErrorRef = useRef(onUpdateError);
  useEffect(() => {
    onUpdateErrorRef.current = onUpdateError;
  }, [onUpdateError]);

  const invoke = (newValue: number) => {
    try {
      onValueRef.current?.(newValue);
    } catch (e) {
      onUpdateErrorRef.current?.(e as Error);
    }
  };

  // Created once — stable across re-renders caused by cart/data events
  // Buttons: 200ms debounce, created once, never recreated
  const debouncedButtonHandler = useRef(debounce(invoke, 200)).current;

  // True while the input debounce timer is still pending.
  // Blur only calls invoke if it's cancelling a live timer — not if the timer already fired.
  const hasPendingInputRef = useRef(false);
  const debouncedInputHandler = useRef(
    debounce((newValue: number) => {
      hasPendingInputRef.current = false;
      invoke(newValue);
    }, 1000),
  ).current;

  // Skip server sync while user is actively typing to prevent flicker
  useEffect(() => {
    const propValue = Number(value);
    if (!isFocusedRef.current && propValue !== currentValue) {
      setCurrentValue(propValue);
      setIsEmpty(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value]);

  return (
    <div
      className={classes([
        'dropin-incrementer',
        `dropin-incrementer--${size}`,
        className,
      ])}
    >
      {label && (
        <label htmlFor={inputId} className="dropin-incrementer__label">
          {label}
        </label>
      )}
      <div
        className={classes([
          'dropin-incrementer__content',
          `dropin-incrementer__content--${size}`,
          ['dropin-incrementer__content--no-buttons', !showButtons],
          [`dropin-incrementer__content--error`, isInvalid],
          [`dropin-incrementer__content--success`, success],
          [`dropin-incrementer__content--disabled`, disabled],
        ])}
      >
        {/* Minus Button */}
        {showButtons && (
          <div
            className={classes([
              'dropin-incrementer__button-container',
              [`dropin-incrementer__button-container--disabled`, disabled],
            ])}
          >
            <Localizer>
              <button
                type="button"
                className={classes([
                  'dropin-incrementer__decrease-button',
                  [`dropin-incrementer__decrease-button--disabled`, disabled],
                ])}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  setIsEmpty(false);
                  debouncedInputHandler.cancel();
                  hasPendingInputRef.current = false;
                  setCurrentValue(currentValue - 1);
                  debouncedButtonHandler(currentValue - 1);
                }}
                disabled={disabled || currentValue < minValue + 1}
                aria-label={
                  (<Text id="Dropin.Incrementer.decreaseLabel" />) as any
                }
              >
                <Icon
                  source={Minus}
                  size="16"
                  stroke="1"
                  viewBox="4 2 20 20"
                  className="dropin-incrementer__down"
                />
              </button>
            </Localizer>
          </div>
        )}

        {/* Input Field */}
        <input
          id={inputId}
          className="dropin-incrementer__input"
          max={max}
          min={min}
          step={1}
          type="number"
          name={name}
          value={isEmpty ? '' : currentValue}
          disabled={disabled}
          aria-valuetext={isEmpty ? undefined : String(currentValue)}
          onFocus={() => {
            isFocusedRef.current = true;
          }}
          onBlur={() => {
            isFocusedRef.current = false;
            debouncedInputHandler.cancel();
            const wasPending = hasPendingInputRef.current;
            hasPendingInputRef.current = false;
            if (
              !isEmpty &&
              wasPending &&
              Number(currentValue) !== Number(value)
            ) {
              invoke(Number(currentValue));
            }
          }}
          onChange={(e) => {
            const newValue = e.currentTarget.value;
            if (newValue === '') {
              setIsEmpty(true);
            } else {
              const numValue = Number(newValue);
              if (numValue === currentValue) return;
              setIsEmpty(false);
              setCurrentValue(numValue);
              debouncedButtonHandler.cancel();
              hasPendingInputRef.current = true;
              debouncedInputHandler(numValue);
            }
          }}
          {...props}
        />

        {showButtons && (
          <div
            className={classes([
              'dropin-incrementer__button-container',
              [`dropin-incrementer__button-container--disabled`, disabled],
            ])}
          >
            {/* Plus/Add button */}
            <Localizer>
              <button
                type="button"
                className={classes([
                  'dropin-incrementer__increase-button',
                  [`dropin-incrementer__increase-button--disabled`, disabled],
                ])}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  setIsEmpty(false);
                  debouncedInputHandler.cancel();
                  hasPendingInputRef.current = false;
                  setCurrentValue(currentValue + 1);
                  debouncedButtonHandler(currentValue + 1);
                }}
                disabled={disabled || currentValue > maxValue - 1}
                aria-label={
                  (<Text id="Dropin.Incrementer.increaseLabel" />) as any
                }
              >
                <Icon
                  source={Add}
                  size="16"
                  stroke="1"
                  viewBox="4 2 20 20"
                  className="dropin-incrementer__add"
                />
              </button>
            </Localizer>
          </div>
        )}
      </div>
      {isInvalid && (
        <p className="dropin-incrementer__content--error-message">
          <Text
            id={errorMessage}
            fields={{ minQuantity: min, maxQuantity: max }}
          />
        </p>
      )}
    </div>
  );
};
