import { Icon } from '@adobe-commerce/elsie/components';
import { ChevronDown } from '@adobe-commerce/elsie/icons';
import { classes } from '@adobe-commerce/elsie/lib';
import { FunctionComponent, VNode } from 'preact';
import {
  HTMLAttributes,
  SelectHTMLAttributes,
  useEffect,
  useRef,
  useState,
} from 'preact/compat';

import '@adobe-commerce/elsie/components/Picker/Picker.css';

type PickerValue = string | null;

export interface PickerOption {
  value: PickerValue;
  text?: string;
  icon?: VNode<HTMLAttributes<SVGSVGElement>>;
  disabled?: boolean;
}

export interface PickerProps extends Omit<
  SelectHTMLAttributes<HTMLSelectElement>,
  'value' | 'size' | 'icon'
> {
  id?: string;
  name?: string;
  value?: PickerValue;
  placeholder?: string;
  variant?: 'primary' | 'secondary';
  size?: 'medium' | 'large';
  floatingLabel?: string;
  icon?: VNode<HTMLAttributes<SVGSVGElement>>;
  options?: PickerOption[];
  defaultOption?: PickerOption;
  disabled?: boolean;
  disableWhenSingle?: boolean;
  error?: boolean;
  handleSelect?: (event: Event) => void;
}

function findSelectedValue(
  value?: PickerValue,
  defaultOption?: PickerOption,
  placeholder?: string,
  floatingLabel?: string,
  firstAvailableOption?: PickerOption,
  singleOption?: PickerOption,
) {
  if (value) return value;
  if (defaultOption) return defaultOption.value;
  // sole option wins over the placeholder so it stays selected, not blank
  if (singleOption) return singleOption.value;
  if (placeholder || floatingLabel) return '';
  if (firstAvailableOption) return firstAvailableOption.value;
  return null;
}

export const Picker: FunctionComponent<PickerProps> = ({
  name,
  value = null,
  options,
  variant = 'primary',
  floatingLabel,
  size = 'medium',
  handleSelect = () => {},
  disabled = false,
  disableWhenSingle = true,
  error = false,
  placeholder,
  defaultOption,
  icon,
  className,
  id,
  ...props
}) => {
  const uniqueId = id ?? name ?? `dropin-picker-${Math.random().toString(36)}`;
  const isRequired = !!props?.required;
  const isDisabled = disabled || (disableWhenSingle && options?.length === 1);
  const selectRef = useRef<HTMLSelectElement>(null);
  const accessibleName = name ?? floatingLabel ?? placeholder;

  // find the first option that is not disabled
  const firstAvailableOption = options?.find((option) => !option.disabled);

  // the only selectable option when the picker auto-disables; a disabled
  // <select> never fires change, so we must emit it ourselves (see below).
  // when disableWhenSingle is false the picker stays interactive, so no
  // special handling is needed.
  const singleOption =
    !disabled &&
    disableWhenSingle &&
    options?.length === 1 &&
    !options[0]?.disabled
      ? options[0]
      : undefined;

  const [selectedValue, setSelectedValue] = useState<PickerValue>(() => {
    return findSelectedValue(
      value,
      defaultOption,
      placeholder,
      floatingLabel,
      firstAvailableOption,
      singleOption,
    );
  });

  useEffect(() => {
    setSelectedValue(
      findSelectedValue(
        value,
        defaultOption,
        placeholder,
        floatingLabel,
        firstAvailableOption,
        singleOption,
      ),
    );
  }, [
    value,
    defaultOption,
    placeholder,
    floatingLabel,
    firstAvailableOption,
    singleOption,
  ]);

  // commit the sole option to the consumer; skip once value has come back in.
  // dispatch a real change event so handleOptionClick emits it: consumers get
  // a genuine Event (some call preventDefault) identical to a user selection.
  useEffect(() => {
    if (!singleOption || value === singleOption.value) return;

    const select = selectRef.current;
    if (!select) return;

    select.value = singleOption.value as string;
    select.dispatchEvent(new Event('change', { bubbles: true }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [singleOption?.value, value]);

  const handleOptionClick = (event: Event) => {
    const { options, value } = event.target as HTMLSelectElement;

    for (const element of options) {
      if (element.selected) {
        setSelectedValue(value);
        handleSelect(event);
      }
    }
  };

  const optionsListItems = options?.map((option) => {
    const { value, text, disabled } = option;
    const selected = value === selectedValue;

    return (
      <option
        value={value as string}
        key={value}
        selected={selected}
        disabled={disabled}
        className={classes(['dropin-picker__option'])}
      >
        {text}
      </option>
    );
  });

  const isSelected = !!selectedValue;

  const hasToDisplayPlaceholder = () => {
    return (!isRequired || !isSelected) && (floatingLabel || placeholder);
  };

  return (
    <div
      className={classes([
        className,
        'dropin-picker',
        `dropin-picker__${size}`,
        ['dropin-picker__floating', !!floatingLabel],
        ['dropin-picker__selected', isSelected],
        ['dropin-picker__error', error],
        ['dropin-picker__disabled', isDisabled],
        ['dropin-picker__icon', icon],
      ])}
    >
      {icon && (
        // @ts-ignore
        <icon.type
          {...icon.props}
          className={'dropin-picker__icon--placeholder'}
        />
      )}

      <select
        ref={selectRef}
        id={uniqueId}
        className={classes([
          'dropin-picker__select',
          `dropin-picker__select--${variant}`,
          `dropin-picker__select--${size}`,
          ['dropin-picker__select--floating', !!floatingLabel],
        ])}
        name={name}
        aria-label={accessibleName}
        disabled={isDisabled}
        onChange={handleOptionClick}
        {...props}
      >
        {hasToDisplayPlaceholder() && (
          <option
            selected={!isSelected}
            value={''}
            key={value}
            className={classes([
              'dropin-picker__option dropin-picker__placeholder',
            ])}
          >
            {floatingLabel ?? placeholder}
          </option>
        )}

        {optionsListItems}
      </select>

      <Icon
        source={ChevronDown}
        size="24"
        stroke="2"
        className="dropin-picker__chevronDown"
      />

      {floatingLabel && isSelected && (
        <label
          htmlFor={uniqueId}
          className={classes(['dropin-picker__floatingLabel', !!floatingLabel])}
        >
          {floatingLabel}
        </label>
      )}
    </div>
  );
};
